-- seed.sql
TRUNCATE users, applications RESTART IDENTITY CASCADE;
-- Users
-- password_hash values are placeholders (not real bcrypt hashes).
-- Replace with real hashes generated by your app if you want to test login.
INSERT INTO users (username, email, password_hash) VALUES
    ('alice_dev',   'alice@example.com',   '$2b$12$placeholderhashalice000000000000000000000000000000000000'),
    ('bob_builder', 'bob@example.com',     '$2b$12$placeholderhashbob00000000000000000000000000000000000000'),
    ('carol_qa',    'Carol@Example.com',   '$2b$12$placeholderhashcarol0000000000000000000000000000000000000'),
    ('dave_empty',  'dave@example.com',    '$2b$12$placeholderhashdave000000000000000000000000000000000000');
-- dave_empty intentionally has no applications (tests empty states)

-- Applications for alice (covers all statuses, varied dates)
INSERT INTO applications (user_id, company, position, status, date_applied, notes)
SELECT u.id, v.company, v.position, v.status::application_status, v.date_applied::date, v.notes
FROM users u
JOIN (VALUES
    ('Google',     'Backend Engineer',          'interviewing', CURRENT_DATE - 30, 'Phone screen done, onsite scheduled'),
    ('Stripe',     'Software Engineer',         'offer',        CURRENT_DATE - 45, 'Offer received, negotiating salary'),
    ('Shopify',    'Senior Developer',          'rejected',     CURRENT_DATE - 60, 'Rejected after take-home assignment'),
    ('Netflix',    'Platform Engineer',         'applied',      CURRENT_DATE - 3,  NULL),
    ('Spotify',    'Data Engineer',             'applied',      CURRENT_DATE - 7,  'Referred by a former colleague'),
    ('Atlassian',  'Full Stack Developer',      'interviewing', CURRENT_DATE - 14, 'Technical interview next week'),
    ('Takealot',   'Backend Developer',         'rejected',     CURRENT_DATE - 90, NULL),
    ('Discovery',  'Software Engineer II',      'applied',      CURRENT_DATE,      'Applied today via company portal')
) AS v(company, position, status, date_applied, notes) ON TRUE
WHERE u.username = 'alice_dev';

-- Applications for bob (fewer, mixed statuses)
INSERT INTO applications (user_id, company, position, status, date_applied, notes)
SELECT u.id, v.company, v.position, v.status::application_status, v.date_applied::date, v.notes
FROM users u
JOIN (VALUES
    ('Microsoft',  'Cloud Engineer',   'applied',      CURRENT_DATE - 5,  NULL),
    ('Amazon',     'SDE I',            'interviewing', CURRENT_DATE - 20, 'Online assessment passed'),
    ('Capitec',    'DevOps Engineer',  'offer',        CURRENT_DATE - 35, 'Verbal offer, awaiting written contract')
) AS v(company, position, status, date_applied, notes) ON TRUE
WHERE u.username = 'bob_builder';

-- Applications for carol (edge cases: long text, special characters, same company twice)
INSERT INTO applications (user_id, company, position, status, date_applied, notes)
SELECT u.id, v.company, v.position, v.status::application_status, v.date_applied::date, v.notes
FROM users u
JOIN (VALUES
    ('O''Reilly Media',  'QA Automation Engineer',    'applied',      CURRENT_DATE - 10, 'Apostrophe in company name'),
    ('Acme Corp',        'QA Engineer',               'rejected',     CURRENT_DATE - 80, 'First attempt'),
    ('Acme Corp',        'Senior QA Engineer',        'interviewing', CURRENT_DATE - 2,  'Reapplied for a senior role'),
    ('Müller & Söhne',   'Test Lead',                 'applied',      CURRENT_DATE - 1,  'Unicode and ampersand test'),
    ('Initech',          'Quality Analyst',           'rejected',     CURRENT_DATE - 120,
        'Long notes test: ' || repeat('This is a long note sentence. ', 20))
) AS v(company, position, status, date_applied, notes) ON TRUE
WHERE u.username = 'carol_qa';